import zipfile
import re
import xml.etree.ElementTree as ET

M = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"

def col_index(ref):
    n = 0
    for ch in re.match(r"([A-Z]+)", ref).group(1):
        n = n * 26 + (ord(ch) - 64)
    return n

path = "budget.xlsx"
z = zipfile.ZipFile(path)

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.iter(f"{{{M}}}si"):
        shared.append("".join(t.text or "" for t in si.iter(f"{{{M}}}t")))

wb = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
rid_to_target = {rel.get("Id"): rel.get("Target") for rel in rels}

sheets = []
for sh in wb.iter(f"{{{M}}}sheet"):
    rid = sh.get(f"{{{R}}}id")
    target = rid_to_target.get(rid, "")
    if not target.startswith("xl/"):
        target = "xl/" + target.lstrip("/")
    sheets.append((sh.get("name"), target))

grand_total = 0.0
for name, target in sheets:
    root = ET.fromstring(z.read(target))
    grid = {}
    for row in root.iter(f"{{{M}}}row"):
        r = int(row.get("r"))
        for c in row:
            if c.tag != f"{{{M}}}c":
                continue
            ref = c.get("r")
            t = c.get("t")
            v = c.find(f"{{{M}}}v")
            if v is None:
                isel = c.find(f"{{{M}}}is")
                val = "".join(tx.text or "" for tx in isel.iter(f"{{{M}}}t")) if isel is not None else ""
            elif t == "s":
                val = shared[int(v.text)]
            elif t in ("str", "b", "e"):
                val = v.text
            else:
                val = v.text
            grid[(r, col_index(ref))] = val
    maxr = max((k[0] for k in grid), default=0)
    maxc = max((k[1] for k in grid), default=0)
    print(f"=== Sheet: {name} ===")
    for r in range(1, maxr + 1):
        print(" | ".join(str(grid.get((r, cidx), "")) for cidx in range(1, maxc + 1)))
    total = 0.0
    for val in grid.values():
        try:
            total += float(val)
        except (TypeError, ValueError):
            pass
    print(f"Sheet numeric sum: {total}")
    grand_total += total

print(f"\nGRAND TOTAL (all numeric cells, all sheets): {grand_total}")

